#Requires -Version 7.0
[CmdletBinding()]param([Parameter(Mandatory)][string]$Story,[Parameter(Mandatory)][ValidateSet('Accept','Reject','Publish','Unpublish','Reopen')][string]$Action,[switch]$AuthorizePublishedReopen,[string]$ProjectRoot)
$ErrorActionPreference='Stop';if([string]::IsNullOrWhiteSpace($ProjectRoot)){$ProjectRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../../..'))}
. (Join-Path $PSScriptRoot 'PipelineCommon.ps1');. (Join-Path $PSScriptRoot 'PipelineTransactions.ps1');Assert-ProductionBranch $ProjectRoot
$dir=Join-Path $ProjectRoot "stories/$Story";$record=Read-PipelineJson(Join-Path $dir 'story.json');if($record.provenance-cne'pipeline'){throw 'Legacy accepted lifecycle records are immutable except through an explicit correction transaction.'}
switch($Action){'Accept'{if($record.status-cne'candidate'){throw 'Accept requires candidate.'};$record.userDisposition='accepted'}'Reject'{$record.stage='abandoned';$record.status='abandoned';$record.canon=$false;$record.userDisposition='rejected';$record.publish=$false;$record.promotionDate=$null}'Publish'{if($record.status-cnotin@('candidate','final')){throw 'Publish requires candidate or final.'};$release=Read-PipelineJson(Join-Path $dir 'release.json');if(-not$release.certified){throw 'Publish requires certified release.'};$record.publish=$true}'Unpublish'{$record.publish=$false}'Reopen'{if($record.status-cne'candidate'){throw 'Only candidates can reopen through this command.'};if($record.publish-and-not$AuthorizePublishedReopen){throw 'Published reopen requires -AuthorizePublishedReopen.'};$record.stage='final-review';$record.status='in-progress';$record.canon=$false;$record.userDisposition='pending';$record.publish=$false;$record.promotionDate=$null}}
$paths=@("stories/$Story/story.json","stories/$Story/README.md","stories/$Story/release.json",'stories/INDEX.md','stories/NAMES.md');Invoke-PipelineTransaction -ProjectRoot $ProjectRoot -Path $paths -Mutation {Write-PipelineJson(Join-Path $dir 'story.json')$record;Set-StoryReadmeProjection(Join-Path $dir 'README.md')$record;Set-StoryIndexProjection(Join-Path $ProjectRoot 'stories/INDEX.md')$record "Lifecycle action: $Action.";if($Action-ceq'Reject'){Set-StoryRegistryState(Join-Path $ProjectRoot 'stories/NAMES.md')$Story 'abandoned' ''};if($Action-ceq'Reopen'){Set-StoryRegistryState(Join-Path $ProjectRoot 'stories/NAMES.md')$Story 'in-progress' ''; $release=Read-PipelineJson(Join-Path $dir 'release.json');$release.certified=$false;$release.certifiedAt=$null;Write-PipelineJson(Join-Path $dir 'release.json')$release}}
$record|ConvertTo-Json -Depth 8
